import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    p = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n+1)]
    in_degree = [0]*(n+1)
    for i in range(1, n+1):
        if p[i-1] != -1:
            adj[p[i-1]].append(i)
            in_degree[i] += 1

    # Topological sort using Kahn's algorithm
    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)

    topo_order = []
    while q:
        u = q.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Assign colors (groups) using greedy approach
    color = [0]*(n+1)
    max_color = 0
    for u in topo_order:
        max_color_in_neighbors = 0
        for v in adj[u]:
            if color[v] > max_color_in_neighbors:
                max_color_in_neighbors = color[v]
        color[u] = max_color_in_neighbors + 1
        if color[u] > max_color:
            max_color = color[u]

    print(max_color)

if __name__ == "__main__":
    main()
